function CDM:GetDefaultAbilityBorderColor(cooldownID, spellID)
    if cooldownID then
        local color = DEFAULT_BORDER_COLORS_BY_COOLDOWN_ID[cooldownID]
        if color then
            return color
        end
    end

    if spellID then
        local color = DEFAULT_BORDER_COLORS_BY_SPELL_ID[spellID]
        if color then
            return color
        end
    end

    return nil
end
